-- ----------------------------
-- Table structure for tb_ai_prompt
-- ----------------------------
DROP TABLE IF EXISTS `tb_ai_prompt`;
CREATE TABLE `tb_ai_prompt`  (
  `id` bigint(0) NOT NULL COMMENT '主键',
  `context_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'KEY',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提示词内容',
  `note` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` bigint(0) NOT NULL DEFAULT -1 COMMENT '创建人',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_user` bigint(0) NOT NULL DEFAULT -1 COMMENT '更新人',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `delete_time` bigint(0) NOT NULL DEFAULT 0 COMMENT '删除时间',
  `create_org` bigint(0) NULL DEFAULT NULL COMMENT '创建部门',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tb_ai_prompt_key_uindex`(`context_key`, `delete_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '提示词表' ROW_FORMAT = Dynamic;

