  CONSTRAINT `tb_core_role_data_ibfk_2` FOREIGN KEY (`role_id`) REFERENCES `tb_core_role` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色数据权限关联表' ROW_FORMAT = Dynamic;

